				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		// Alumno: solo ve su propio estado de cuenta
if ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "estudiante_id = " . intval($_SESSION["estudiante_id"]));
}

// Filtro de pestañas (Tabs)
if (isset($_GET["f_tab"])) {
    $_SESSION["pagos_tab"] = $_GET["f_tab"];
}
$tab = isset($_SESSION["pagos_tab"]) ? $_SESSION["pagos_tab"] : "todos";

if ($tab == "vencidos") {
    $strWhereClause = whereAdd($strWhereClause, "estado = 'Vencido' OR (estado = 'Pendiente' AND fecha_vencimiento < CURDATE())");
} elseif ($tab == "pendientes") {
    $strWhereClause = whereAdd($strWhereClause, "estado = 'Pendiente' AND fecha_vencimiento >= CURDATE()");
} elseif ($tab == "pagados") {
    $strWhereClause = whereAdd($strWhereClause, "estado = 'Pagado'");
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before display
function BeforeShowList(&$xt, &$templatefile, &$pageObject)
{

		// Si se está filtrando por un estudiante específico, mostrar su resumen bancario
if (isset($_SESSION["pagos_masterrecord"])) {
    $est_id = intval($_SESSION["pagos_masterrecord"]["id"]);
    
    $rsResumen = DB::Query("SELECT 
        COUNT(CASE WHEN nro_cuota LIKE '%/%' THEN 1 END) AS total_cuotas,
        COUNT(CASE WHEN nro_cuota LIKE '%/%' AND estado = 'Pagado' THEN 1 END) AS pagadas,
        COUNT(CASE WHEN nro_cuota LIKE '%/%' AND estado != 'Pagado' THEN 1 END) AS pendientes,
        SUM(CASE WHEN estado != 'Pagado' THEN (monto - descuento + multa_mora) ELSE 0 END) AS saldo_total
        FROM pagos WHERE estudiante_id = $est_id");
        
    if ($res = $rsResumen->fetchAssoc()) {
        $xt->assign("message", "<div class='alert alert-info' style='font-size: 14px; font-weight: 600; margin-bottom: 15px;'>
            <i class='fa fa-bank'></i> Estado de Cuenta: 
            <strong>" . $res["pagadas"] . " de " . $res["total_cuotas"] . " cuotas pagadas</strong> &bull; 
            Pendientes: " . $res["pendientes"] . " &bull; 
            Saldo Total Adeudado: <span style='color: #c0392b;'>Gs. " . number_format($res["saldo_total"], 0, ',', '.') . "</span>
        </div>");
    }
}


// Contar registros por cada pestaña en 1 sola consulta rápida
$tab_actual = isset($_SESSION["pagos_tab"]) ? $_SESSION["pagos_tab"] : "todos";

$sqlCounts = "SELECT 
    COUNT(*) AS total,
    SUM(CASE WHEN estado = 'Vencido' THEN 1 ELSE 0 END) AS vencidos,
    SUM(CASE WHEN estado = 'Pendiente' THEN 1 ELSE 0 END) AS pendientes,
    SUM(CASE WHEN estado = 'Pagado' THEN 1 ELSE 0 END) AS pagados
    FROM pagos";

// Si es alumno, contar solo lo suyo
if ($_SESSION["rol"] == 'Alumno') {
    $sqlCounts .= " WHERE estudiante_id = " . intval($_SESSION["estudiante_id"]);
}

$rsCounts = DB::Query($sqlCounts);
$counts = $rsCounts->fetchAssoc();

// Enviar datos al navegador
$pageObject->setProxyValue("tab_counts", $counts);
$pageObject->setProxyValue("active_tab", $tab_actual);

if ($_SESSION["rol"] == 'Alumno') {
    $est_id = intval($_SESSION["estudiante_id"]);
    
    // Consultar cuotas vencidas
    $rsDeuda = DB::Query("SELECT COUNT(*) AS vencidas, SUM(monto + multa_mora - descuento) AS saldo_vencido 
                          FROM pagos 
                          WHERE estudiante_id = " . $est_id . " AND estado = 'Vencido'");
    $rDeuda = $rsDeuda->fetchAssoc();
    $cantVencidas = intval($rDeuda["vencidas"]);
    $saldoVencido = intval($rDeuda["saldo_vencido"]);

    if ($cantVencidas > 0) {
        $xt->assign("message", '
        <div class="alert alert-danger" style="font-size: 14px; border-left: 5px solid #c0392b; margin-bottom: 15px;">
            <i class="fa fa-exclamation-circle fa-lg"></i> 
            <strong>Aviso de Tesorería:</strong> Posee <strong>' . $cantVencidas . ' cuota(s) vencida(s)</strong> por un total de 
            <strong>Gs. ' . number_format($saldoVencido, 0, ',', '.') . '</strong>. 
            Recuerde regularizar su cuenta para evitar el <em>Bloqueo Financiero</em> en los Exámenes Finales.
        </div>');
    } else {
        $xt->assign("message", '
        <div class="alert alert-success" style="font-size: 13px; border-left: 5px solid #27ae60; margin-bottom: 15px;">
            <i class="fa fa-check-circle fa-lg"></i> 
            <strong>¡Excelente!</strong> Su estado de cuenta se encuentra al día. Está habilitado para rendir evaluaciones finales.
        </div>');
    }
}
;		
} // function BeforeShowList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$monto     = intval(round($values["monto"]));
$descuento = intval(round($values["descuento"]));
$estado    = $values["estado"];
$metodo    = trim($values["metodo_pago"]);
$venc      = $values["fecha_vencimiento"];
$hoy       = date("Y-m-d");

// 1. Validaciones financieras
if ($monto <= 0) {
    $message = "El importe a facturar debe ser mayor a Gs. 0.";
    return false;
}

if ($descuento > $monto) {
    $message = "El descuento no puede ser superior al monto total.";
    return false;
}

if ($estado == "Pagado" && empty($metodo)) {
    $message = "Para registrar un pago con estado 'Pagado', debe seleccionar obligatoriamente el Método de Pago.";
    return false;
}

// 2. Control de fechas y moras (2% mensual escalonado)
if ($estado == "Pagado") {
    if (empty($values["fecha_pago"])) {
        $values["fecha_pago"] = date("Y-m-d H:i:s");
    }
} else {
    $values["fecha_pago"] = null;
    
    // Si venció y sigue pendiente, actualizar estado y calcular mora
    if (!empty($venc) && $venc < $hoy) {
        $values["estado"] = "Vencido";
        $diasAtraso = (strtotime($hoy) - strtotime($venc)) / 86400;
        $meses = max(1, ceil($diasAtraso / 30));
        $values["multa_mora"] = intval(round($monto * 0.02 * $meses));
    } else {
        $values["multa_mora"] = 0;
        if ($values["estado"] == "Vencido") {
            $values["estado"] = "Pendiente";
        }
    }
}

$values["monto"]      = $monto;
$values["descuento"]  = $descuento;
$values["multa_mora"] = intval(round($values["multa_mora"]));

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
