				// List page: After record processed
function BeforeMoveNextList(&$data, &$row, &$record, $recordId, &$pageObject)
{

		// Formateo de moneda Guaraníes
$row["monto_value"] = '<strong>Gs. ' . number_format(intval($data["monto"]), 0, ',', '.') . '</strong>';

if (intval($data["multa_mora"]) > 0) {
    $row["multa_mora_value"] = '<span style="color:#c0392b; font-weight:700;">+ Gs. ' . number_format(intval($data["multa_mora"]), 0, ',', '.') . '</span>';
} else {
    $row["multa_mora_value"] = '<span class="text-muted">Gs. 0</span>';
}

if (intval($data["descuento"]) > 0) {
    $row["descuento_value"] = '<span style="color:#27ae60; font-weight:700;">- Gs. ' . number_format(intval($data["descuento"]), 0, ',', '.') . '</span>';
}

// Formateo de badge de estado
if ($data["estado"] == "Pagado") {
    $row["estado_value"] = '<span class="label label-success" style="font-size:11px; padding:3px 8px;"><i class="fa fa-check"></i> Pagado</span>';
} elseif ($data["estado"] == "Vencido" || ($data["estado"] == "Pendiente" && $data["fecha_vencimiento"] < date("Y-m-d"))) {
    $row["estado_value"] = '<span class="label label-danger" style="font-size:11px; padding:3px 8px;"><i class="fa fa-exclamation-triangle"></i> Vencido</span>';
} else {
    $row["estado_value"] = '<span class="label label-warning" style="font-size:11px; padding:3px 8px; color:#000;"><i class="fa fa-clock-o"></i> Pendiente</span>';
}
;		
} // function BeforeMoveNextList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



